112	// Policies returns all canonical policies in deterministic order.
113	func (c *Catalog) Policies() []Policy {
114		names := make([]string, 0, len(c.manifest.Policies))
115		for name := range c.manifest.Policies {
116			names = append(names, name)
117		}
118		sort.Strings(names)
119		out := make([]Policy, 0, len(names))
120		for _, name := range names {
121			policy, _ := c.Policy(name)
122			out = append(out, policy)
123		}
124		return out
125	}
