127	// Policy returns one canonical policy definition.
128	func (c *Catalog) Policy(name string) (Policy, bool) {
129		name = strings.TrimSpace(name)
130		entry, ok := c.manifest.Policies[name]
131		if !ok {
132			return Policy{}, false
133		}
134		return Policy{
135			Name:       name,
136			MinPower:   entry.MinPower,
137			MaxPower:   entry.MaxPower,
138			AllowLocal: entry.AllowLocal,
139			Require:    append([]string(nil), entry.Require...),
140		}, true
141	}
