143	// Providers returns all catalog-declared provider systems in deterministic order.
144	func (c *Catalog) Providers() []Provider {
145		names := make([]string, 0, len(c.manifest.Providers))
146		for name := range c.manifest.Providers {
147			names = append(names, name)
148		}
149		sort.Strings(names)
150		out := make([]Provider, 0, len(names))
151		for _, name := range names {
152			entry := c.manifest.Providers[name]
153			billing := BillingModel(entry.Billing)
154			if billing == BillingModelUnknown {
155				billing = BillingForProviderSystem(entry.Type)
156				if billing == BillingModelUnknown {
157					billing = BillingForHarness(entry.Type)
158				}
159			}
160			out = append(out, Provider{
161				Name:             name,
162				Type:             entry.Type,
163				IncludeByDefault: entry.IncludeByDefault,
164				Billing:          billing,
165			})
166		}
167		return out
168	}
