211	// Resolve resolves a canonical policy or model ID to a concrete model ID.
212	func (c *Catalog) Resolve(ref string, opts ResolveOptions) (ResolvedTarget, error) {
213		ref = strings.TrimSpace(ref)
214		if ref == "" {
215			return ResolvedTarget{}, &UnknownReferenceError{Ref: ref}
216		}
217		if opts.Surface == "" {
218			return ResolvedTarget{}, &MissingSurfaceError{CanonicalID: ref, Surface: opts.Surface}
219		}
220		if policy, ok := c.policyForReference(ref); ok {
221			return c.resolvePolicy(ref, policy, opts)
222		}
223		if entry, ok := c.manifest.Models[ref]; ok && surfaceModelID(ref, entry, opts.Surface) == "" {
224			return ResolvedTarget{}, &MissingSurfaceError{CanonicalID: ref, Surface: opts.Surface}
225		}
226		if modelID, entry, ok := c.lookupModelVariant(ref); ok && surfaceModelID(modelID, entry, opts.Surface) == "" {
227			return ResolvedTarget{}, &MissingSurfaceError{CanonicalID: modelID, Surface: opts.Surface}
228		}
229		modelID, entry, concrete, ok := c.modelForSurface(ref, opts.Surface)
230		if !ok {
231			return ResolvedTarget{}, &UnknownReferenceError{Ref: ref}
232		}
233		return c.resolvedFromModel(ref, "", modelID, concrete, entry, opts)
234	}
