236	func (c *Catalog) resolvePolicy(ref string, policy Policy, opts ResolveOptions) (ResolvedTarget, error) {
237		displayName := policyDisplayNameForRef(ref, policy.Name)
238		candidates := c.policyCandidates(policy, opts.Surface)
239		if len(candidates) == 0 {
240			return ResolvedTarget{}, &MissingSurfaceError{CanonicalID: displayName, Surface: opts.Surface}
241		}
242		best := candidates[0]
243		return c.resolvedFromModel(ref, displayName, best.modelID, best.concrete, best.entry, opts)
244	}
