246	type policyCandidate struct {
247		modelID  string
248		concrete string
249		entry    ModelEntry
250	}
251	
252	func (c *Catalog) policyCandidates(policy Policy, surface Surface) []policyCandidate {
253		ids := make([]string, 0, len(c.manifest.Models))
254		for id := range c.manifest.Models {
255			ids = append(ids, id)
256		}
257		sort.Strings(ids)
258		out := make([]policyCandidate, 0, len(ids))
259		for _, id := range ids {
260			entry := c.manifest.Models[id]
261			if !entry.AutoRoutable() {
262				continue
263			}
264			if policy.MinPower > 0 && entry.Power < policy.MinPower {
265				continue
266			}
267			if policy.MaxPower > 0 && entry.Power > policy.MaxPower {
268				continue
269			}
270			if requiresNoRemote(policy) && !isLocalDeployment(entry.DeploymentClass) {
271				continue
272			}
273			if !policy.AllowLocal && isLocalDeployment(entry.DeploymentClass) {
274				continue
275			}
276			concrete := surfaceModelID(id, entry, surface)
277			if concrete == "" {
278				continue
279			}
280			out = append(out, policyCandidate{modelID: id, concrete: concrete, entry: entry})
281		}
282		sort.SliceStable(out, func(i, j int) bool {
283			if out[i].entry.Power != out[j].entry.Power {
284				return out[i].entry.Power > out[j].entry.Power
285			}
286			if out[i].entry.CostInputPerM != out[j].entry.CostInputPerM {
287				return out[i].entry.CostInputPerM < out[j].entry.CostInputPerM
288			}
289			return out[i].modelID < out[j].modelID
290		})
291		return out
292	}
