312	func (c *Catalog) resolvedFromModel(ref, policyName, modelID, concrete string, entry ModelEntry, opts ResolveOptions) (ResolvedTarget, error) {
313		status := normalizedStatus(entry.Status)
314		if status != statusActive && !opts.AllowDeprecated {
315			return ResolvedTarget{}, &DeprecatedTargetError{CanonicalID: modelID, Status: status}
316		}
317		return ResolvedTarget{
318			Ref:                ref,
319			Profile:            policyName,
320			Family:             entry.Family,
321			CanonicalID:        canonicalIDForResolved(policyName, modelID),
322			ConcreteModel:      concrete,
323			SurfacePolicy:      SurfacePolicy{ReasoningDefault: entry.ReasoningDefault},
324			Deprecated:         status != statusActive,
325			CatalogVersion:     c.manifest.CatalogVersion,
326			ManifestSource:     c.manifestSrc,
327			ManifestVersion:    c.manifest.Version,
328			CostInputPerM:      entry.inputCostPerM(),
329			CostOutputPerM:     entry.outputCostPerM(),
330			CostCacheReadPerM:  entry.CostCacheReadPerM,
331			CostCacheWritePerM: entry.CostCacheWritePerM,
332			ContextWindow:      entry.ContextWindow,
333			SWEBenchVerified:   entry.SWEBenchVerified,
334			LiveCodeBench:      entry.LiveCodeBench,
335			BenchmarkAsOf:      entry.BenchmarkAsOf,
336			OpenRouterRefID:    entry.openRouterID(),
337		}, nil
338	}
