347	func (c *Catalog) modelForSurface(ref string, surface Surface) (string, ModelEntry, string, bool) {
348		if entry, ok := c.manifest.Models[ref]; ok {
349			concrete := surfaceModelID(ref, entry, surface)
350			return ref, entry, concrete, concrete != ""
351		}
352		for modelID, entry := range c.manifest.Models {
353			for _, concrete := range entry.Surfaces {
354				if concrete == ref {
355					return modelID, entry, concrete, true
356				}
357			}
358		}
359		if modelID, entry, ok := c.lookupModelVariant(ref); ok {
360			concrete := surfaceModelID(modelID, entry, surface)
361			return modelID, entry, concrete, concrete != ""
362		}
363		return "", ModelEntry{}, "", false
364	}
365	
366	func surfaceModelID(modelID string, entry ModelEntry, surface Surface) string {
367		if surface == "" {
368			return ""
369		}
370		if concrete := entry.Surfaces[string(surface)]; concrete != "" {
371			return concrete
372		}
373		if _, ok := entry.Surfaces[""]; ok {
374			return modelID
375		}
376		return ""
377	}
