379	// AllConcreteModels returns a map from concrete model ID to canonical model ID
380	// for every active model that has a mapping for the given surface.
381	func (c *Catalog) AllConcreteModels(surface Surface) map[string]string {
382		ids := make([]string, 0, len(c.manifest.Models))
383		for id := range c.manifest.Models {
384			ids = append(ids, id)
385		}
386		sort.Strings(ids)
387		out := make(map[string]string)
388		for _, id := range ids {
389			entry := c.manifest.Models[id]
390			if normalizedStatus(entry.Status) != statusActive {
391				continue
392			}
393			if concrete := surfaceModelID(id, entry, surface); concrete != "" {
394				out[concrete] = id
395			}
396		}
397		return out
398	}
