400	// CandidatesFor returns the ordered concrete model IDs for a policy or model.
401	func (c *Catalog) CandidatesFor(surface Surface, key string) []string {
402		if policy, ok := c.policyForReference(key); ok {
403			candidates := c.policyCandidates(policy, surface)
404			out := make([]string, 0, len(candidates))
405			for _, candidate := range candidates {
406				out = append(out, candidate.concrete)
407			}
408			return out
409		}
410		if _, _, concrete, ok := c.modelForSurface(key, surface); ok {
411			return []string{concrete}
412		}
413		return nil
414	}
