416	func (c *Catalog) policyForReference(ref string) (Policy, bool) {
417		if policy, ok := c.Policy(ref); ok {
418			return policy, true
419		}
420		switch strings.TrimSpace(ref) {
421		case "standard", "code-fast", "fast":
422			return c.Policy("default")
423		case "code-smart":
424			return c.Policy("smart")
425		case "code-economy", "local", "offline":
426			return c.Policy("cheap")
427		}
428		return Policy{}, false
429	}
