479	// LookupModel returns the ModelEntry for the given model ID.
480	func (c *Catalog) LookupModel(id string) (ModelEntry, bool) {
481		if entry, ok := c.manifest.Models[id]; ok {
482			return entry, true
483		}
484		for _, entry := range c.manifest.Models {
485			for _, concrete := range entry.Surfaces {
486				if concrete == id {
487					return entry, true
488				}
489			}
490		}
491		if _, entry, ok := c.lookupModelVariant(id); ok {
492			return entry, true
493		}
494		return ModelEntry{}, false
495	}
