497	// ModelEligibility returns power and automatic-routing eligibility for a
498	// catalog model ID or any declared provider surface ID. Unknown models return
499	// ok=false; known models with missing/zero power remain exact-pin-capable but
500	// are not auto-routable.
501	func (c *Catalog) ModelEligibility(id string) (ModelEligibility, bool) {
502		entry, ok := c.LookupModel(id)
503		if !ok {
504			for modelID, candidate := range c.manifest.Models {
505				if strings.EqualFold(modelID, id) {
506					entry = candidate
507					ok = true
508					break
509				}
510				for _, surfaceID := range candidate.Surfaces {
511					if strings.EqualFold(surfaceID, id) {
512						entry = candidate
513						ok = true
514						break
515					}
516				}
517				if ok {
518					break
519				}
520			}
521			if !ok {
522				return ModelEligibility{}, false
523			}
524		}
525		return ModelEligibility{
526			Power:        entry.Power,
527			ExactPinOnly: entry.ExactPinOnly,
528			AutoRoutable: entry.AutoRoutable(),
529		}, true
530	}
531	
532	// ContextWindowForModel returns the context window in tokens for the given
533	// concrete model ID, or 0 if the model is not in the catalog or has no
534	// context_window declared. Used as a fallback when the provider's live API
535	// does not expose its context window (e.g. LM Studio's /v1/models omits it).
536	// Matching is case-insensitive to accept both "qwen3.5-27b" and "Qwen3.5-27B".
537	func (c *Catalog) ContextWindowForModel(id string) int {
538		if entry, ok := c.LookupModel(id); ok && entry.ContextWindow > 0 {
539			return entry.ContextWindow
540		}
541		best := 0
542		id = strings.TrimSpace(id)
543		if id == "" {
544			return 0
545		}
546		for modelID, entry := range c.manifest.Models {
547			if strings.EqualFold(modelID, id) || sameModelVariant(id, modelID) {
548				if entry.ContextWindow > best {
549					best = entry.ContextWindow
550				}
551			}
552			for _, concrete := range entry.Surfaces {
553				if strings.EqualFold(concrete, id) || sameModelVariant(id, concrete) {
554					if entry.ContextWindow > best {
555						best = entry.ContextWindow
556					}
557				}
558			}
559		}
560		if best > 0 {
561			return best
562		}
563		return 0
564	}
565	
566	// SupportsToolsForModel reports whether the given concrete model ID supports
567	// tool/function calling per the catalog. Returns true when the model is not
568	// in the catalog (caller assumes capable by default) and false only when the
569	// catalog explicitly marks the model with no_tools=true. Matching is
570	// case-insensitive to mirror ContextWindowForModel.
571	func (c *Catalog) SupportsToolsForModel(id string) bool {
572		if c == nil {
573			return true
574		}
575		if entry, ok := c.LookupModel(id); ok {
576			return !entry.NoTools
577		}
578		return true
579	}
