581	func (c *Catalog) lookupModelVariant(id string) (string, ModelEntry, bool) {
582		id = strings.TrimSpace(id)
583		if id == "" {
584			return "", ModelEntry{}, false
585		}
586		var (
587			best     ModelEntry
588			bestID   string
589			bestSeen bool
590		)
591		for modelID, entry := range c.manifest.Models {
592			matched := sameModelVariant(id, modelID)
593			if !matched {
594				for _, surfaceID := range entry.Surfaces {
595					if sameModelVariant(id, surfaceID) {
596						matched = true
597						break
598					}
599				}
600			}
601			if !matched {
602				continue
603			}
604			if !bestSeen || betterModelVariantMatch(entry, modelID, best, bestID) {
605				best = entry
606				bestID = modelID
607				bestSeen = true
608			}
609		}
610		if !bestSeen {
611			return "", ModelEntry{}, false
612		}
613		return bestID, best, true
614	}
615	
616	func betterModelVariantMatch(candidate ModelEntry, candidateID string, best ModelEntry, bestID string) bool {
617		candidateStatus := normalizedStatus(candidate.Status)
618		bestStatus := normalizedStatus(best.Status)
619		if candidateStatus != bestStatus {
620			return statusRank(candidateStatus) > statusRank(bestStatus)
621		}
622		if candidate.Power != best.Power {
623			return candidate.Power > best.Power
624		}
625		if candidate.ContextWindow != best.ContextWindow {
626			return candidate.ContextWindow > best.ContextWindow
627		}
628		if candidate.ExactPinOnly != best.ExactPinOnly {
629			return !candidate.ExactPinOnly && best.ExactPinOnly
630		}
631		return candidateID < bestID
632	}
633	
634	func statusRank(status string) int {
635		switch normalizedStatus(status) {
636		case statusActive:
637			return 2
638		case statusDeprecated:
639			return 1
640		case statusStale:
641			return 0
642		default:
643			return -1
644		}
645	}
646	
647	func sameModelVariant(a, b string) bool {
648		ca := catalogModelKey(a)
649		cb := catalogModelKey(b)
650		if ca == "" || cb == "" {
651			return false
652		}
653		if ca == cb {
654			return true
655		}
656		if sameNamedFamilyMajor(a, b) {
657			return true
658		}
659		if len(ca) < 8 || len(cb) < 8 {
660			return false
661		}
662		return strings.Contains(ca, cb) || strings.Contains(cb, ca)
663	}
664	
665	func catalogModelKey(s string) string {
666		s = strings.TrimSpace(s)
667		if slash := strings.Index(s, "/"); slash > 0 {
668			s = s[slash+1:]
669		}
670		s = strings.ToLower(s)
671		var b strings.Builder
672		b.Grow(len(s))
673		for _, r := range s {
674			switch {
675			case r >= 'a' && r <= 'z':
676				b.WriteRune(r)
677			case r >= '0' && r <= '9':
678				b.WriteRune(r)
679			}
680		}
681		return b.String()
682	}
683	
684	func sameNamedFamilyMajor(a, b string) bool {
685		familyA, majorA := namedFamilyMajor(a)
686		familyB, majorB := namedFamilyMajor(b)
