242			}
243			if model.CostOutputPerM < 0 || model.CostOutputPerMTok < 0 {
244				return fmt.Errorf("model %q cost_output_per_m must be >= 0", modelID)
245			}
246			if model.CostCacheReadPerM < 0 {
247				return fmt.Errorf("model %q cost_cache_read_per_m must be >= 0", modelID)
248			}
249			if model.CostCacheWritePerM < 0 {
250				return fmt.Errorf("model %q cost_cache_write_per_m must be >= 0", modelID)
251			}
252			if model.ContextWindow < 0 {
253				return fmt.Errorf("model %q context_window must be >= 0", modelID)
254			}
255			if model.Power < 0 {
256				return fmt.Errorf("model %q power must be >= 0", modelID)
257			}
258			if model.Power > 10 {
259				return fmt.Errorf("model %q power must be <= 10", modelID)
260			}
261			if model.ReasoningMaxTokens < 0 {
262				return fmt.Errorf("model %q reasoning_max_tokens must be >= 0", modelID)
263			}
264			for level, budget := range model.ReasoningBudgets {
265				if budget < 0 {
