267				}
268				if model.ReasoningMaxTokens > 0 && budget > model.ReasoningMaxTokens {
269					return fmt.Errorf("model %q reasoning_budgets %q exceeds reasoning_max_tokens", modelID, level)
270				}
271			}
272			switch model.ReasoningDefault {
273			case "", reasoning.ReasoningOff, reasoning.ReasoningLow, reasoning.ReasoningMedium, reasoning.ReasoningHigh, reasoning.ReasoningMax, reasoning.ReasoningXHigh:
274			default:
275				return fmt.Errorf("model %q has invalid reasoning_default %q", modelID, model.ReasoningDefault)
276			}
277			switch model.ReasoningControl {
278			case "", ReasoningControlTunable, ReasoningControlFixed, ReasoningControlNone:
279			default:
280				return fmt.Errorf("model %q has invalid reasoning_control %q (must be one of tunable, fixed, none)", modelID, model.ReasoningControl)
281			}
282			switch model.ReasoningWire {
283			case "", ReasoningWireProvider, ReasoningWireModelID, ReasoningWireNone, ReasoningWireEffort, ReasoningWireTokens:
