8	const (
9		deploymentClassManagedCloudFrontier = "managed_cloud_frontier"
10		deploymentClassPrepaidFrontier      = "prepaid_frontier"
11		deploymentClassMeteredCloud         = "metered_cloud"
12		deploymentClassLocalFree            = "local_free"
13		deploymentClassCommunitySelfHosted  = "community_self_hosted"
14	)
15	
16	// BootstrapModelPowers derives conservative power/eligibility defaults from
17	// comparable model metadata. It is side-effect-free so catalog generation can
18	// inspect or persist the result explicitly.
19	func BootstrapModelPowers(models map[string]ModelEntry) map[string]ModelEntry {
20		out := make(map[string]ModelEntry, len(models))
21		for id, model := range models {
22			out[id] = model
23		}
24	
25		groups := make(map[string][]string)
26		for id, model := range out {
27			key := model.Family + "\x00" + model.DeploymentClass
28			groups[key] = append(groups[key], id)
29		}
30	
31		for _, ids := range groups {
32			sort.Slice(ids, func(i, j int) bool {
33				left, right := out[ids[i]], out[ids[j]]
34				if cmp := strings.Compare(powerRecency(left), powerRecency(right)); cmp != 0 {
35					return cmp > 0
36				}
37				if leftCost, rightCost := powerCost(left), powerCost(right); leftCost != rightCost {
38					return leftCost > rightCost
39				}
40				if left.SWEBenchVerified != right.SWEBenchVerified {
41					return left.SWEBenchVerified > right.SWEBenchVerified
42				}
43				return ids[i] < ids[j]
44			})
45	
46			for rank, id := range ids {
47				model := out[id]
48				if normalizedStatus(model.Status) != statusActive {
49					continue
50				}
51				if rank > 0 && strings.TrimSpace(model.PowerProvenance.OverrideReason) == "" {
52					model.Power = 0
53					model.ExactPinOnly = true
54					out[id] = model
55					continue
56				}
57				if model.Power <= 0 {
58					model.Power = defaultPowerForDeploymentClass(model.DeploymentClass)
59				}
60				if cap := powerCapForDeploymentClass(model.DeploymentClass); model.Power > cap {
61					model.Power = cap
62				}
63				out[id] = model
64			}
65		}
66	
67		return out
68	}
69	
70	func powerRecency(model ModelEntry) string {
71		if model.PowerProvenance.Recency != "" {
72			return model.PowerProvenance.Recency
73		}
74		return model.BenchmarkAsOf
75	}
76	
77	func powerCost(model ModelEntry) float64 {
78		input := model.PowerProvenance.CostInputPerM
79		if input == 0 {
80			input = model.inputCostPerM()
81		}
82		output := model.PowerProvenance.CostOutputPerM
83		if output == 0 {
84			output = model.outputCostPerM()
85		}
86		return input + output
87	}
88	
89	func defaultPowerForDeploymentClass(class string) int {
90		switch strings.TrimSpace(class) {
91		case deploymentClassManagedCloudFrontier, deploymentClassPrepaidFrontier:
92			return 9
93		case deploymentClassMeteredCloud:
94			return 7
95		case deploymentClassLocalFree, deploymentClassCommunitySelfHosted:
96			return 5
97		default:
98			return 4
99		}
100	}
101	
102	func powerCapForDeploymentClass(class string) int {
103		switch strings.TrimSpace(class) {
104		case deploymentClassLocalFree, deploymentClassCommunitySelfHosted:
105			return 6
106		default:
107			return 10
108		}
109	}
